async function lowestOwnedSeat(snapshot, token, address, nextSerial, signal) {
  const iface = await contractInterface('AFKING_SUB_TOKEN');
  const ranges = [];
  for (let from = 1; from < nextSerial; from += OWNER_BATCH) ranges.push([from, Math.min(nextSerial, from + OWNER_BATCH)]);
  for (let i = 0; i < ranges.length; i += OWNER_CALLS_AT_ONCE) {
    const found = await Promise.all(ranges.slice(i, i + OWNER_CALLS_AT_ONCE).map(async ([from, to]) => {
      const calls = [];
      for (let id = from; id < to; id++) calls.push([token, true, iface.encodeFunctionData('ownerOf', [id])]);
      const raw = await snapshot.client.atBlock('eth_call', [{ to: MULTICALL, data: multicall.encodeFunctionData('aggregate3', [calls]) }], snapshot, signal);
      // Never read a failed or short batch as "every seat burned".
      if (!raw || raw === '0x') throw new ChainDataError('Seat ownership is unavailable. Please try again.');
      const [results] = multicall.decodeFunctionResult('aggregate3', raw);
      if (results.length !== calls.length) throw new ChainDataError('Invalid Multicall response.');
      for (let k = 0; k < results.length; k++) {
        // A burned or unminted serial reverts InvalidToken: success is false.
        if (!results[k].success) continue;
        const [owner] = iface.decodeFunctionResult('ownerOf', results[k].returnData);
        if (owner.toLowerCase() === address) return BigInt(from + k);
      }
      return null;
    }));
    checkAbort(signal);
    const seat = found.find(id => id != null);
    if (seat != null) return seat;
  }
  return null;
}
